#!/usr/bin/env bash
# sigortalab deposunu senin adina olusturup GitHub'a gonderir.
set -e
cd "$(dirname "$0")"

mkdir -p .github/workflows
base64 -d > .github/workflows/devsecops.yml <<'B64'

B64

if ! gh auth status >/dev/null 2>&1; then
  echo ">> GitHub girisi gerekiyor, tarayici acilacak..."
  gh auth login
fi

git init -q
git add -A
git -c user.name="Zehra Nur Kolsuz" -c user.email="zehrakolsuzis@gmail.com" \
    commit -q -m "SigortaLab: aciklim sigorta portali + DevSecOps hatti"
git branch -M main
gh repo create sigortalab --public --source=. --remote=origin --push

echo ""
echo ">> Tamam! Depo: https://github.com/$(gh api user -q .login)/sigortalab"
echo ">> Actions sekmesinde hat calismaya baslayacak."
